// <diletta-data-list> — a INSTÂNCIA WEB de `design-system-data-list`.
//
// A peça que faltava. Eu tinha modelado a linha, a célula, o cabeçalho de coluna e
// a linha de cabeçalho — quatro peças soltas, sem nada que as juntasse. No arquivo
// elas moram todas dentro de um List Container que É a peça: é ele que decide o
// respiro entre linhas, o recuo de 16 e o rodapé.
import './diletta-data-header-row.js';
import './diletta-pagination.js';

// Medido em 88 instâncias: linhas de 54 andam de 62 em 62, as de 52 de 68 em 68, e
// as de 64 de 64 em 64 — passo IGUAL à altura, ou seja, encostadas.
const RESPIRO = { tabela: 8, painel: 16, historico: 0 };
const RECUO = 16;

class DilettaDataList extends HTMLElement {
  static observedAttributes = ['porte', 'colunas', 'contagem', 'paginas', 'atual', 'rotulo', 'vazio'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  get porte() {
    const v = this.getAttribute('porte');
    return RESPIRO[v] !== undefined ? v : 'tabela';
  }

  get vazia() {
    return this.hasAttribute('vazio') || this.querySelectorAll('diletta-data-row').length === 0;
  }

  /// O VAZIO se decide DEPOIS, e por `slotchange`.
  ///
  /// A primeira versão perguntava `this.vazia` dentro do `render()` e desenhava um
  /// ou o outro. Consequência medida no navegador: uma lista preenchida por
  /// `innerHTML` depois de conectada renderizava "Nada por aqui" e nunca mais
  /// voltava — as linhas chegavam e ninguém contava de novo.
  ///
  /// > **Filho de luz que chega depois é o caso NORMAL, não a exceção.** Componente
  /// > que lê os filhos uma vez no construtor só funciona em HTML estático.
  ///
  /// Por isso os dois blocos existem SEMPRE, e o que muda é `hidden`: o slot
  /// precisa estar no shadow desde o começo para que `slotchange` dispare.
  atualizaVazio() {
    const r = this.shadowRoot;
    if (!r) return;
    const vazia = this.vazia;
    r.querySelector('.itens').hidden = vazia;
    r.querySelector('.vazio').hidden = !vazia;
    const rodape = r.querySelector('.rodape');
    if (rodape) rodape.hidden = vazia;
  }

  render() {
    const porte = this.porte;
    const colunas = this.getAttribute('colunas') || '';
    const contagem = this.getAttribute('contagem') || '';
    const paginas = Number(this.getAttribute('paginas') || 0);
    // O rodapé é DECLARADO pelos atributos; quem o esconde na lista vazia é
    // `atualizaVazio`. Paginar o nada é oferecer navegação para lugar nenhum.
    const rodape = contagem || paginas > 1;

    let r;
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        /* Reset do hidden. O display EXPLÍCITO desta peça vence a regra do
           navegador, e sem esta linha o estado vazio continuava desenhado embaixo
           das linhas — com o atributo ligado e o teste verde. O culpado é o CSS da
           própria peça, não o atributo. (Sem crase: template literal.) */
        [hidden] { display: none !important; }
        /* O 16 é o ritmo da peça inteira: recuo de cada borda E separação entre os
           três blocos. A largura de 917 no arquivo é 949 menos os dois recuos —
           ninguém repete a subtração. */
        .lista {
          box-sizing: border-box; padding: ${RECUO}px;
          display: flex; flex-direction: column; gap: ${RECUO}px;
          /* UM POÇO: surfaceSubtle, que no vocabulário é "fundo de seção: separa
             sem virar card". O desenho pinta com o tom da tela e eu havia
             declarado bg; a decisão pelo NOME é do dono, de 07/09. Do lado do pai
             é ganho puro: na referência bg e surface são o mesmo branco, então só
             com surfaceSubtle o poço fica visível no catálogo.
             Medido em tela, não em nó isolado — em isolado os 16px de recuo saem
             iguais ao que está atrás e parecem transparência. */
          background: var(--cps-surfaceSubtle);
          border-radius: var(--cps-r24, 24px);
        }
        /* O RESPIRO É DA COLEÇÃO, não da linha — a mesma regra do separador no
           DilettaAppList. Linha que declara a própria margem põe margem depois da
           última. */
        .itens { display: flex; flex-direction: column; gap: ${RESPIRO[porte]}px; }
        /* No porte encostado as linhas se tocam, com régua entre elas e nenhuma
           depois da última. (Sem crase: isto mora num template literal.) */
        .itens.divide ::slotted(diletta-data-row:not(:last-child)) {
          border-bottom: 1px solid var(--cps-border);
        }
        .rodape {
          height: 30px; display: flex; align-items: center;
          justify-content: space-between; gap: 16px;
        }
        .contagem { color: var(--cps-textSecondary); }
        .vazio { padding: 32px 0; display: flex; justify-content: center; }
      </style>
      <div class="lista" part="lista" role="table"
           aria-label="${(this.getAttribute('rotulo') || 'Lista de dados').replace(/"/g, '&quot;')}">
        ${colunas ? `<diletta-data-header-row colunas="${colunas.replace(/"/g, '&quot;')}"
            porte="${porte === 'painel' ? 'compacto' : 'regular'}"></diletta-data-header-row>` : ''}
        <div class="itens ${porte === 'historico' ? 'divide' : ''}" role="rowgroup"><slot></slot></div>
        <div class="vazio" role="status"><slot name="vazio">Nada por aqui.</slot></div>
        ${rodape ? `<div class="rodape">
            <span class="contagem">${contagem}</span>
            ${paginas > 1 ? `<diletta-pagination paginas="${paginas}"
                atual="${this.getAttribute('atual') || 1}"></diletta-pagination>` : '<span></span>'}
          </div>` : ''}
      </div>`;

    // O slot já está no shadow: agora o `slotchange` tem onde disparar.
    r = this.shadowRoot.querySelector('slot:not([name])');
    r.addEventListener('slotchange', () => this.atualizaVazio());
    this.atualizaVazio();
  }
}

customElements.define('diletta-data-list', DilettaDataList);
export { DilettaDataList, RESPIRO, RECUO };
